-- c001-v002: Duba ƙarami na–sa–ka cikin–al'ummai wulakantacce kai sosai
-- c001-v003: girman–kai na–zuciyarka ya–ruɗe–ka mai–zaune a–cikin–tsagayen dutse tudu mazauninsa mai–ce a–cikin–zuciyarsa wane–ne zai–saukar–da–ni ƙasa
-- c001-v004: ko–da ka–ɗaga kamar–gaggafa ko–da a–tsakanin taurari ka–sa sheƙarka daga–can zan–saukar–da–ka in–ji Yahweh
-- c001-v005: idan ɓarayi sun–zo wurinka idan masu–fashi na–dare yaya aka–yi–maka–shiru ko ba–za–su–sata isa–musu idan masu–girbin–inabi sun–zo wurinka ko ba–za–su–bari ƙwayoyin–da–suka–rage
-- c001-v006: Yaya aka–bincika Isuwa aka–tono ɓoyayyunsa
-- c001-v007: har iyaka sun–tura–ka dukan mutanen alƙawarinka sun–ruɗe–ka sun–ci–nasara–kan–ka wurinka mutanen salama–taka abincinku sun–sa tarko ƙarƙashinka babu fahimta a–cikinsa
-- c001-v008: Ko a–ranar nan in–ji Yahweh zan–hallaka masu–hikima daga–Edom da–fahimta daga–dutsen Isuwa
-- c001-v009: za–a–firgita jarumawanku Teman domin a–yanke kowane–mutum daga–dutsen Isuwa ta–kisa
-- c001-v010: Saboda–zalunci ga–ɗan'uwanka Yakubu kunya–za–ta–rufe–ka kunya za–a–yanke–ka har–abada
-- c001-v011: A–ranar da–ka–tsaya a–nesa a–ranar baƙi sun–kwashe arzikinsa da–baƙi sun–shiga ƙofofinsa ƙofofinsa kuma–kan Urushalima sun–jefa ƙuri'a har kai kamar–ɗaya daga–cikinsu
-- c001-v012: Kada ka–duba a–ranar ɗan'uwanka a–ranar masifar–sa kada ka–yi–murna kan–'ya'yan Yahuda a–ranar hallakar–su kada ka–yi–girman–kai bakinka a–ranar wahala
-- c001-v013: Kada ka–shiga ƙofar mutanena a–ranar masifar–su kada ka–duba har kai masifarsa a–ranar masifarsa kada ka–miƙa–hannuwanka ga–arzikinsa a–ranar masifarsa
-- c001-v014: Kada ka–tsaya kan mararraba don–ka–yanke nan masu–tserensu kada ka–ba–da masu–raguwarsu a–ranar wahala
-- c001-v015: Gama kusa ranar Yahweh kan dukan al'ummai yadda ka–yi za–a–yi maka ayyukanka za–su–komo kan–kanka
-- c001-v016: Gama kamar–yadda kun–sha kan dutsen tsarkina dukan–al'ummai–za–su–sha dukan al'ummai kullum za–su–sha su–haɗiye za–su–zama kamar ba–su–taɓa–kasancewa
-- c001-v017: Amma–kan–dutsen Sihiyona za–a–sami masu–tsira zai–zama tsarki gidan–Yakubu–za–su–mallaka gidan Yakubu nan dukiyoyinsu
-- c001-v018: Gidan–Yakubu–zai–zama gidan Yakubu wuta gidan Yusufu harshen–wuta gidan Isuwa tattaka za–su–ƙone–su a–cikinsu su–cinye–su ba–za–a–sami wanda–ya–tsira mai–ragewa ga–gidan Isuwa gama Yahweh ya–faɗa
-- c001-v019: Za–su–mallaka Negeb nan dutsen Isuwa da–Shefela nan Filistiyawa za–su–mallaka nan filin Ifraimu da filin Samariya Biliyaminu nan Gileyad
-- c001-v020: Kuma–'yan–gudun–hijira na–runduna nan na–'ya'yan Isra'ila waɗanda Kan'anawa har Sarfat da–'yan–gudun–hijira na–Urushalima waɗanda a–Sefarad za–su–mallaka nan biranen Negeb
